/*
 * The wavetable engine for patch/synths (included by synths.c).
 *
 * One engine voice per voice of a WAVE slot (a VAP voice object whose patch has WAVE's
 * model id). It reads the slot's copy of the parameters (synths.c keeps it from
 * set_param) and renders 128 mono float samples per block into L, as a VAP voice does.
 * WAVE's parameters sit at VAP's indices (synths.c's builder renames and re-ranges
 * VAP's), so the index map below is VAP's.
 *
 * Oscillators (x2). Wave 1 / Wave 2 (0-8) pick one of 9 slots: the 7 banks of
 * wt_tables.h (generated by gen_wavetables.py), the super saw, or a saw. A bank has 32 frames,
 * each stored as band-limited levels. Per block the level is chosen so the highest
 * harmonic stays below 20 kHz; per sample the oscillator interpolates linearly inside
 * the frame and between the two frames around its position (Position 1 / 2), which is
 * ramped across the block. The phase is a 32-bit accumulator. Digital mode plays the
 * banks the way early digital wavetable synths did: the nearest frame, no
 * interpolation, 8-bit samples. The super saw is 7 band-limited saws spread around the
 * note (Position sets the spread), with the relative detunes measured from the Roland
 * JP-8000's; the saw is its centre saw alone. Each voice's oscillators start at their
 * own phases.
 *
 * Modulation, per block: a mod envelope (23-26, VAP's Env 1), two LFOs with VAP's
 * parameters (27-34: Ratio in Hz, or a tempo division with Sync; Waveform; Retrigger
 * Note, One Shot or Free Running) and a Polarity each (60, 61: WAVE's own, after VAP's
 * 60; Bipolar -1..1, Unipolar 0..1), and a 6-slot Mod Matrix (42-59: Src, Dest, Amt)
 * from the envelopes, the LFOs, velocity and key to Position, Pitch, Mix, Cutoff,
 * Resonance, Volume and Noise.
 *
 * Filters, after VAP's 15 filter types (all topology-preserving, stable at any setting):
 * MG is a 4-pole low-pass (a transistor-ladder model) with a saturating input stage;
 * the PPG Wave and ESQ-1 have analog 4-pole (24 dB) low-passes too. OB is a 2-pole
 * state-variable filter whose band-pass state saturates, after the Oberheim SEM's; SVF
 * is the clean 2-pole one.
 * The 24 dB OB and SVF types put a second, unresonant stage before it. Cutoff, envelope
 * and key tracking are set per block. Drive (38) puts the filter's input through a soft
 * clip first, up to +24 dB into it, with the level made up; at 0 there is no such stage.
 *
 * Envelopes (x3, ADSR): advanced once per block, a linear attack and exponential decay
 * and release; the amp envelope is ramped across the block. As in VAP, parameters
 * 19-22 are the amp envelope; WAVE's filter envelope is 15-18 (VAP's Env 2; VAP's own filter
 * envelope is 23-26, docs/FINDINGS.md section 23). The
 * amp envelope's end makes the voice idle: "sounding" is false and the render writes
 * 128 zeros.
 */
#ifndef WT_ENGINE_H
#define WT_ENGINE_H

#include "wt_tables.h"

#define WT_ENGINE_ON        1
#define WT_BLOCK            128u
#define WT_RATE             44100.0f
#define WT_MAX_HZ           20000.0f        /* the highest harmonic a level may reach */

/* The parameters (set_param indices: VAP's, then WAVE's own) that the engine reads, and
 * their place in a slot's parameter copy (the effect's, 62-65, are wt_fx.h's). WP_SHAPE is WAVE's Position, WP_WAVE its
 * Wave. */
#define VAP_PARAMS          60u
#define WAVE_PARAMS         66u             /* VAP's 60, LFO 1's and LFO 2's Polarity, the effect's 4 */
#define VAP_VOLUME          39u             /* velocity / 127, set per voice before each note */
enum {
    WP_SHAPE1, WP_SHAPE2, WP_WAVE1, WP_WAVE2, WP_MIX, WP_TUNE1, WP_TUNE2, WP_DETUNE, WP_FINE,
    WP_RESET1, WP_RESET2, WP_TYPE, WP_CUTOFF, WP_RES, WP_ENVAMT,
    WP_FENV_ATT, WP_FENV_DEC, WP_FENV_SUS, WP_FENV_REL,     /* 15-18: the filter envelope */
    WP_AENV_ATT, WP_AENV_DEC, WP_AENV_SUS, WP_AENV_REL,     /* 19-22: the amp envelope */
    WP_GLIDE_MODE, WP_GLIDE_TIME, WP_TRACK, WP_DIGITAL, WP_NOISE,
    WP_MENV_ATT, WP_MENV_DEC, WP_MENV_SUS, WP_MENV_REL,     /* 23-26: the mod envelope (VAP's Env 1) */
    WP_LFO1, WP_LFO2 = WP_LFO1 + 4,                         /* 27-30, 31-34: Ratio, Waveform, Retrigger, Sync */
    WP_MTX = WP_LFO2 + 4,                                   /* 42-59: 6 x Src, Dest, Amt */
    WP_DRIVE = WP_MTX + 18,                                 /* 38: Drive (VAP's unused Mix Env Amt) */
    WP_LFO_POL,                                             /* 60, 61: LFO 1's and LFO 2's Polarity */
    WT_PARAMS = WP_LFO_POL + 2
};
#define WT_UNUSED           0xFFu
static const uint8_t wt_param_slot[WAVE_PARAMS] = {
    WP_SHAPE1, WP_SHAPE2, WP_WAVE1, WP_WAVE2, WP_MIX, WP_TUNE1, WP_TUNE2, WP_DETUNE, WP_FINE,
    WP_RESET1, WP_RESET2, WP_TYPE, WP_CUTOFF, WP_RES, WP_ENVAMT,                     /* 0-14 */
    WP_FENV_ATT, WP_FENV_DEC, WP_FENV_SUS, WP_FENV_REL,                              /* 15-18 */
    WP_AENV_ATT, WP_AENV_DEC, WP_AENV_SUS, WP_AENV_REL,                              /* 19-22 */
    WP_MENV_ATT, WP_MENV_DEC, WP_MENV_SUS, WP_MENV_REL,                              /* 23-26 */
    WP_LFO1, WP_LFO1 + 1, WP_LFO1 + 2, WP_LFO1 + 3, WP_LFO2, WP_LFO2 + 1, WP_LFO2 + 2, WP_LFO2 + 3,  /* 27-34 */
    WP_GLIDE_MODE, WP_GLIDE_TIME, WP_TRACK, WP_DRIVE, WT_UNUSED, WP_DIGITAL, WP_NOISE,   /* 35-41 */
    WP_MTX, WP_MTX + 1, WP_MTX + 2, WP_MTX + 3, WP_MTX + 4, WP_MTX + 5,               /* 42-59 */
    WP_MTX + 6, WP_MTX + 7, WP_MTX + 8, WP_MTX + 9, WP_MTX + 10, WP_MTX + 11,
    WP_MTX + 12, WP_MTX + 13, WP_MTX + 14, WP_MTX + 15, WP_MTX + 16, WP_MTX + 17,
    WP_LFO_POL, WP_LFO_POL + 1,                                                       /* 60-61 */
    WT_UNUSED, WT_UNUSED, WT_UNUSED, WT_UNUSED,                                       /* 62-65: wt_fx.h */
};

#define MSG_NOTE_ON         4u
#define MSG_NOTE_OFF        5u
#define MSG_BEND            8u
#define BEND_OCTAVES        1.0173768e-05f  /* VAP: octaves = value * 2 * this (+-8192: +-2 semitones) */

#define ENV_IDLE            0u
#define ENV_ATTACK          1u
#define ENV_DECAY           2u
#define ENV_SUSTAIN         3u
#define ENV_RELEASE         4u
struct wt_env { uint32_t stage; float level; };

#define SS_SIDES            6u              /* super saw: the saws beside the centre one */

/* One engine voice, tied to one VAP voice object (owner). */
struct wt_voice {
    uint32_t owner;                         /* the VAP voice object, 0 = free */
    uint32_t slot;
    float volume;                           /* Volume (39): velocity / 127 */
    uint32_t phase[2];
    float pos[2];                           /* frame positions, 0..WT_FRAMES - 1 */
    float note;                             /* the note being played */
    float pitch;                            /* where the glide is (a note number) */
    float glide_step;                       /* semitones per block towards `note` */
    float bend;                             /* semitones */
    struct wt_env aenv, fenv;               /* amp and filter envelopes */
    float ic[4];                            /* filter states: two stages, two each, or the ladder's 4 */
    uint32_t noise;                         /* noise generator (and the super saw's phases) */
    uint8_t gate;                           /* a note is held */
    uint8_t started;                        /* the voice has played a note (for glide) */
    uint8_t fresh;                          /* a new note: positions jump, no ramp */
    uint8_t pad;
    uint32_t side[2][SS_SIDES];             /* super saw: each oscillator's side saws' phases */
    struct wt_env menv;                     /* the mod envelope (a Mod Matrix source) */
    uint32_t lfo_phase[2];                  /* the LFOs (Mod Matrix sources), per voice */
    float lfo_hold[2];                      /* Random S&H: the value held this cycle */
    uint8_t lfo_done[2];                    /* One Shot: the cycle has run */
    uint8_t pad2[2];
};

/* ---- maths ------------------------------------------------------------------------ */

/* x clamped to lo..hi; NaN gives lo */
static inline float clampf(float x, float lo, float hi)
{
    if (!(x >= lo))
        return lo;
    return x > hi ? hi : x;
}

/* 2^x for x in -100..100 (relative error under 2e-6) */
static float exp2f_fast(float x)
{
    x = clampf(x, -100.0f, 100.0f);
    int i = (int)(x + 128.0f) - 128;
    float f = x - (float)i;
    float p = 1.0f + f * (0.69314718f + f * (0.24022651f + f * (0.05550411f + f * (0.00961813f
              + f * (0.00133336f + f * 0.00015404f)))));
    union { float f; int32_t i; } u = { p };
    u.i += i << 23;
    return u.f;
}

static inline float note_hz(float note)
{
    return 440.0f * exp2f_fast((note - 69.0f) * (1.0f / 12.0f));
}

/* ---- the voice ---------------------------------------------------------------------- */

static void wt_voice_init(struct wt_voice *e, uint32_t slot)
{
    e->slot = slot;
    e->volume = 1.0f;
    /* the oscillators start anywhere, each voice elsewhere (from its address): a chord on
     * fresh voices would otherwise start every saw in step, and its first peak clip */
    e->noise = 0x12345678u ^ (uint32_t)e;
    for (uint32_t k = 0; k < 2; k++) {
        e->noise = e->noise * 1664525u + 1013904223u;
        e->phase[k] = e->noise;
    }
    e->pos[0] = e->pos[1] = 0.0f;
    e->note = e->pitch = 60.0f;
    e->glide_step = 0.0f;
    e->bend = 0.0f;
    e->aenv.stage = e->fenv.stage = ENV_IDLE;
    e->aenv.level = e->fenv.level = 0.0f;
    for (uint32_t k = 0; k < 4; k++)
        e->ic[k] = 0.0f;

    for (uint32_t o = 0; o < 2; o++)
        for (uint32_t k = 0; k < SS_SIDES; k++)
            e->side[o][k] = 0;
    e->gate = 0;
    e->started = 0;
    e->fresh = 1;
    e->menv.stage = ENV_IDLE;
    e->menv.level = 0.0f;
    for (uint32_t k = 0; k < 2; k++) {
        e->lfo_phase[k] = 0;
        e->lfo_hold[k] = 0.0f;
        e->lfo_done[k] = 0;
    }
}

/* ---- the LFOs (VAP's Ratio, Waveform, Retrigger, Sync) -------------------------------- */

#define LFO_NOTE            0u              /* Retrigger: from the start at each note */
#define LFO_ONE_SHOT        1u              /* ... once, then hold */
#define LFO_FREE            2u              /* ... never restarted */
#define LFO_SH              5u              /* Waveform: Random S&H */

static uint32_t list_pick(float v, uint32_t count)  /* a stepped parameter's item; NaN gives 0 */
{
    return (uint32_t)(clampf(v, 0.0f, (float)(count - 1u)) + 0.5f);
}

static float lfo_random(struct wt_voice *e)
{
    e->noise = e->noise * 1664525u + 1013904223u;
    return (float)(int32_t)e->noise * (1.0f / 2147483648.0f);
}

/* the length of each Sync division, in beats (VAP's names: 1, 1/2 D, 1/2, 1/4 D, 1 T, 1/4,
 * 1/8 D, 1/2 T, 1/8, 1/16 D, 1/4 T, 1/16, 1/8 T, 1/32, 1/16 T, 1/32 T) */
static const float lfo_beats[16] = {
    4.0f, 3.0f, 2.0f, 1.5f, 4.0f / 3.0f, 1.0f, 0.75f, 2.0f / 3.0f, 0.5f, 0.375f, 1.0f / 3.0f, 0.25f,
    1.0f / 6.0f, 0.125f, 1.0f / 12.0f, 1.0f / 24.0f,
};

/* sin(2 pi t) for t in [0, 1): a parabola, refined (error under 0.1 %) */
static inline float sin_cycle(float t)
{
    float x = 2.0f * t - 1.0f;              /* -1..1 over the cycle: sin(2 pi t) = -sin(pi x) */
    float y = 4.0f * x * (1.0f - (x < 0.0f ? -x : x));
    y = 0.225f * (y * (y < 0.0f ? -y : y) - y) + y;
    return -y;
}

/* One block of LFO k: advances it and returns its value: -1..1, or 0..1 when its
 * Polarity is Unipolar. Ratio is Hz (0-100), or with Sync a division of the tempo (ctx's
 * BPM). */
static float lfo_step(struct wt_voice *e, uint32_t k, const float *p, float tempo)
{
    const float *q = &p[WP_LFO1 + 4u * k];
    float hz;
    if (q[3] > 0.5f)
        hz = clampf(tempo, 20.0f, 999.0f) * (1.0f / 60.0f) / lfo_beats[list_pick(q[0], 16)];
    else
        hz = q[0];
    hz = clampf(hz, 0.0f, 100.0f);          /* also keeps a block's step below a whole cycle */
    uint32_t mode = list_pick(q[2], 3), wave = list_pick(q[1], 6);
    uint32_t ph = e->lfo_phase[k];
    if (!(mode == LFO_ONE_SHOT && e->lfo_done[k])) {
        uint32_t next = ph + (uint32_t)(hz * (4294967296.0f * WT_BLOCK / WT_RATE));
        if (next < ph) {                    /* a new cycle */
            if (mode == LFO_ONE_SHOT) {
                e->lfo_done[k] = 1;
                next = 0xFFFFFFFFu;
            }
            e->lfo_hold[k] = lfo_random(e);
        }
        e->lfo_phase[k] = ph = next;
    }
    float t = (float)(ph >> 8) * (1.0f / 16777216.0f), v;
    switch (wave) {
    case 0: v = 1.0f - 4.0f * (t < 0.5f ? 0.5f - t : t - 0.5f); break;  /* Triangle: -1 at the start */
    case 1: v = sin_cycle(t); break;
    case 2: v = 2.0f * t - 1.0f; break;                                  /* Ramp Up */
    case 3: v = 1.0f - 2.0f * t; break;                                  /* Ramp Down */
    case 4: v = t < 0.5f ? 1.0f : -1.0f; break;                          /* Square */
    default: v = e->lfo_hold[k]; break;                                  /* Random S&H */
    }
    return p[WP_LFO_POL + k] > 0.5f ? 0.5f * (v + 1.0f) : v;             /* Unipolar: 0..1 */
}

static void wt_note_on(struct wt_voice *e, const float *p, uint32_t note)
{
    float n = (float)note;
    float t = clampf(p[WP_GLIDE_TIME], 0.0f, 10.0f);
    uint32_t mode = (uint32_t)clampf(p[WP_GLIDE_MODE] + 0.5f, 0.0f, 3.0f);
    int overlap = e->gate;                  /* the voice still holds a note */
    /* Glide Mode: 0 Always, 1 Overlap (only from a held note), 2 Legato (always, and from
     * a held note the envelopes go on), 3 Legato O. (both only from a held note) */
    int glide = e->started && t > 0.0f && (mode == 0 || mode == 2 || overlap);
    int legato = overlap && mode >= 2;
    if (glide) {
        float d = n - e->pitch;
        e->glide_step = (d < 0 ? -d : d) / (t * (WT_RATE / WT_BLOCK));
    } else {
        e->pitch = n;
        e->glide_step = 0.0f;
    }
    e->note = n;
    for (uint32_t o = 0; o < 2; o++) {
        if (p[WP_RESET1 + o] > 0.5f) {      /* Reset: from phase 0; the side saws spread evenly */
            e->phase[o] = 0;
            for (uint32_t k = 0; k < SS_SIDES; k++)
                e->side[o][k] = (k + 1) * 0x24924925u;
        } else if (e->aenv.stage == ENV_IDLE) {
            for (uint32_t k = 0; k < SS_SIDES; k++) {   /* a new note: the side saws anywhere */
                e->noise = e->noise * 1664525u + 1013904223u;
                e->side[o][k] = e->noise;
            }
        }
    }
    if (e->aenv.stage == ENV_IDLE)
        e->fresh = 1;
    if (!legato) {                          /* attack again from where the envelopes are */
        e->aenv.stage = ENV_ATTACK;
        e->fenv.stage = ENV_ATTACK;
        e->menv.stage = ENV_ATTACK;
        for (uint32_t k = 0; k < 2; k++)
            if (list_pick(p[WP_LFO1 + 4u * k + 2u], 3) != LFO_FREE) {
                e->lfo_phase[k] = 0;
                e->lfo_done[k] = 0;
                e->lfo_hold[k] = lfo_random(e);
            }
    }
    e->gate = 1;
    e->started = 1;
}

static void wt_note_off(struct wt_voice *e)
{
    e->gate = 0;
    if (e->aenv.stage != ENV_IDLE)
        e->aenv.stage = ENV_RELEASE;
    if (e->fenv.stage != ENV_IDLE)
        e->fenv.stage = ENV_RELEASE;
    if (e->menv.stage != ENV_IDLE)
        e->menv.stage = ENV_RELEASE;
}

static void wt_voice_midi(struct wt_voice *e, const uint8_t *msg, const float *p)
{
    uint32_t type = msg[0];
    if (type == MSG_NOTE_ON && msg[3]) {
        wt_note_on(e, p, msg[2]);
    } else if (type == MSG_NOTE_ON || type == MSG_NOTE_OFF) {
        if ((float)msg[2] == e->note && e->gate)
            wt_note_off(e);
    } else if (type == MSG_BEND) {
        int16_t v = (int16_t)(msg[2] | msg[3] << 8);
        e->bend = (float)v * (2.0f * 12.0f * BEND_OCTAVES);
    }
    /* types 0 and 1 (clock tick and transport start, for VAP's synced LFOs): nothing */
}

static int wt_voice_sounding(const struct wt_voice *e)
{
    return e->aenv.stage != ENV_IDLE;
}

/* ---- envelopes and filter -------------------------------------------------------- */

#define ENV_DT              (WT_BLOCK / WT_RATE)
#define ENV_OCTAVES_DOWN    9.9657843f      /* a decay or release takes its time to fall 60 dB */
#define ENV_END             1.0e-3f         /* -60 dB: the release has ended (as VAP's, about) */
#define ENV_NEAR            1.0e-4f         /* the decay has reached the sustain level */

/* the per-block factor of an exponential segment that falls 60 dB in t seconds */
static inline float env_factor(float t)
{
    return exp2f_fast(-ENV_OCTAVES_DOWN * ENV_DT / clampf(t, 0.001f, 10.0f));
}

/* One block of an ADSR (adsr: attack, decay, sustain, release as VAP stores them: times in
 * seconds, sustain 0..1); returns the level at the block's end */
static float env_step(struct wt_env *v, const float *adsr)
{
    float s = clampf(adsr[2], 0.0f, 1.0f);
    switch (v->stage) {
    case ENV_ATTACK: {
        float a = clampf(adsr[0], 0.0f, 10.0f);
        v->level = clampf(v->level, 0.0f, 1.0f) + (a > ENV_DT ? ENV_DT / a : 1.0f);
        if (v->level >= 1.0f) {
            v->level = 1.0f;
            v->stage = ENV_DECAY;
        }
        break;
    }
    case ENV_DECAY:
        v->level = s + (v->level - s) * env_factor(adsr[1]);
        if (v->level - s < ENV_NEAR && s - v->level < ENV_NEAR) {
            v->level = s;
            v->stage = ENV_SUSTAIN;
        }
        break;
    case ENV_SUSTAIN:
        v->level = s;
        break;
    case ENV_RELEASE:
        v->level *= env_factor(adsr[3]);
        if (!(v->level >= ENV_END)) {       /* NaN ends it too */
            v->level = 0.0f;
            v->stage = ENV_IDLE;
        }
        break;
    default:
        v->level = 0.0f;
        v->stage = ENV_IDLE;
        break;
    }
    return v->level;
}

/* VAP's filter types: 0 LP MG 24dB, 1 LP OB 24dB, 2 LP OB 12dB, 3 LP SVF 24dB, 4 LP SVF 12dB,
 * 5 HP OB 24dB, 6 HP OB 12dB, 7 HP SVF 24dB, 8 HP SVF 12dB, 9 BP OB 24dB, 10 BP OB 12dB,
 * 11 BP SVF 24dB, 12 BP SVF 12dB, 13 Notch SVF 24dB, 14 Notch SVF 12dB: the response, the
 * slope and the flavour (MG: the ladder; OB: the saturating SVF; SVF: the clean one). */
#define F_LP                0u
#define F_HP                1u
#define F_BP                2u
#define F_NOTCH             3u
#define F_24DB              4u
#define F_OB                8u
#define F_LADDER            16u
static const uint8_t wt_filter_type[15] = {
    F_LADDER, F_LP | F_24DB | F_OB, F_LP | F_OB, F_LP | F_24DB, F_LP,
    F_HP | F_24DB | F_OB, F_HP | F_OB, F_HP | F_24DB, F_HP,
    F_BP | F_24DB | F_OB, F_BP | F_OB, F_BP | F_24DB, F_BP,
    F_NOTCH | F_24DB, F_NOTCH,
};

/* a soft clip close to tanh: linear near 0, +-1 from +-3 (a rational approximation) */
static inline float sat(float x)
{
    x = x > 3.0f ? 3.0f : (x < -3.0f ? -3.0f : x);
    float x2 = x * x;
    return x * (27.0f + x2) / (27.0f + 9.0f * x2);
}

/* tan(x) for 0 <= x <= 1.3 (cutoff up to 18.2 kHz), a Pade approximation (error under 0.3 %) */
static inline float tan_pade(float x)
{
    float x2 = x * x;
    return x * (15.0f - x2) / (15.0f - 6.0f * x2);
}

/* One SVF's coefficients and output mix: y = m0 x + m1 v1 + m2 v2 */
struct wt_svf { float a1, a2, a3, m0, m1, m2; };

static void svf_setup(struct wt_svf *f, float g, float k, uint32_t type)
{
    f->a1 = 1.0f / (1.0f + g * (g + k));
    f->a2 = g * f->a1;
    f->a3 = g * f->a2;
    switch (type & 3u) {
    case F_HP: f->m0 = 1.0f; f->m1 = -k; f->m2 = -1.0f; break;
    case F_BP: f->m0 = 0.0f; f->m1 = 1.0f; f->m2 = 0.0f; break;
    case F_NOTCH: f->m0 = 1.0f; f->m1 = -k; f->m2 = 0.0f; break;
    default: f->m0 = 0.0f; f->m1 = 0.0f; f->m2 = 1.0f; break;
    }
}

static inline float svf_run(const struct wt_svf *f, float *ic, float x)
{
    float v3 = x - ic[1];
    float v1 = f->a1 * ic[0] + f->a2 * v3;
    float v2 = ic[1] + f->a2 * ic[0] + f->a3 * v3;
    ic[0] = 2.0f * v1 - ic[0];
    ic[1] = 2.0f * v2 - ic[1];
    return f->m0 * x + f->m1 * v1 + f->m2 * v2;
}

/* The OB flavour: the same, with the band-pass state saturating (so the resonance
 * compresses instead of growing); clipping a state only takes energy out, so it stays
 * stable */
#define OB_LEVEL            1.5f            /* where the band-pass state starts to saturate */

static inline float ob_run(const struct wt_svf *f, float *ic, float x)
{
    float v3 = x - ic[1];
    float v1 = f->a1 * ic[0] + f->a2 * v3;
    float v2 = ic[1] + f->a2 * ic[0] + f->a3 * v3;
    ic[0] = sat((2.0f * v1 - ic[0]) * (1.0f / OB_LEVEL)) * OB_LEVEL;
    ic[1] = 2.0f * v2 - ic[1];
    return f->m0 * x + f->m1 * v1 + f->m2 * v2;
}

/* The ladder: 4 one-pole TPT low-passes in series with feedback k from the last. The
 * loop is solved for its input u as if linear, u = (x - k S) / (1 + k G^4), where
 * y4 = G^4 u + S; then u saturates, which bounds the self-oscillation at the top of
 * Resonance. G = g / (1 + g) per block. */
struct wt_ladder { float G, k, gain, inv, c1, c2, c3, c4; };
#define LADDER_K_MAX        4.2f            /* Resonance 150 %: just past self-oscillation (4) */
#define LADDER_COMP         0.85f           /* passband loss with resonance, mostly made up (VAP's Init level) */
#define LADDER_LEVEL        1.0f            /* the input level where the saturation starts */

static void ladder_setup(struct wt_ladder *l, float g, float res)
{
    float G = g / (1.0f + g), G2 = G * G;
    l->G = G;
    l->k = res * (LADDER_K_MAX / 1.5f);
    l->gain = (1.0f + l->k * LADDER_COMP) * (1.0f / LADDER_LEVEL);
    l->inv = 1.0f / (1.0f + l->k * G2 * G2);
    l->c1 = G2 * G * (1.0f - G);            /* S = c1 s1 + c2 s2 + c3 s3 + c4 s4 */
    l->c2 = G2 * (1.0f - G);
    l->c3 = G * (1.0f - G);
    l->c4 = 1.0f - G;
}

static inline float ladder_run(const struct wt_ladder *l, float *s, float x)
{
    float S = l->c1 * s[0] + l->c2 * s[1] + l->c3 * s[2] + l->c4 * s[3];
    float u = sat((x * l->gain - l->k * S) * l->inv);
    float G = l->G, H = 1.0f - G;
    float y1 = G * u + H * s[0];
    s[0] = 2.0f * y1 - s[0];
    float y2 = G * y1 + H * s[1];
    s[1] = 2.0f * y2 - s[1];
    float y3 = G * y2 + H * s[2];
    s[2] = 2.0f * y3 - s[2];
    float y4 = G * y3 + H * s[3];
    s[3] = 2.0f * y4 - s[3];
    return y4 * LADDER_LEVEL;
}

/* One oscillator's per-block setup */
#define WT_SLOTS            (WT_BANKS + 2u) /* Wave's slots: the banks, the super saw, a saw */
#define SLOT_SUPERSAW       WT_BANKS
#define SLOT_SAW            (WT_BANKS + 1u)
#define OSC_BANK            0u              /* wt_osc.supersaw: a bank */
#define OSC_SUPERSAW        1u
#define OSC_SAW             2u              /* the super saw's centre saw alone */
/* the side saws' frequencies, relative to the centre one's, at full spread (from analyses
 * of the JP-8000's super saw) */
static const float ss_detune[SS_SIDES] = {-0.11002313f, -0.06288439f, -0.01952356f,
                                          0.01991221f, 0.06216538f, 0.10745242f};
#define SS_SIDE_GAIN        0.6f            /* each side saw against the centre one */
#define SS_NORM             0.5623f         /* 1 / sqrt(1 + 6 x 0.6^2): about one saw's level */

struct wt_osc { const int16_t *base; uint32_t inc, len, supersaw, digital; float pos, dpos;
                uint32_t side_inc[SS_SIDES]; };

/* `pos_mod`: the Mod Matrix's offset to Position (0-1 is the whole range) */
static void osc_setup(struct wt_osc *o, const struct wt_voice *e, const float *p, uint32_t k, float note,
                      float pos_mod)
{
    float hz = clampf(note_hz(note), 1.0f, WT_MAX_HZ);
    o->inc = (uint32_t)(hz * (4294967296.0f / WT_RATE));
    uint32_t slot = (uint32_t)(clampf(p[WP_WAVE1 + k], 0.0f, (float)(WT_SLOTS - 1)) + 0.5f);
    float shape = clampf(clampf(p[WP_SHAPE1 + k], 0.0f, 1.0f) + clampf(pos_mod, -4.0f, 4.0f), 0.0f, 1.0f);
    o->supersaw = slot == SLOT_SUPERSAW ? OSC_SUPERSAW : slot == SLOT_SAW ? OSC_SAW : OSC_BANK;
    o->digital = !o->supersaw && p[WP_DIGITAL] > 0.5f;
    float top = hz;
    if (o->supersaw == OSC_SUPERSAW) {      /* Position: the spread, finer at the bottom */
        float spread = shape * shape;
        for (uint32_t i = 0; i < SS_SIDES; i++)
            o->side_inc[i] = o->inc + (uint32_t)(int32_t)((float)o->inc * (ss_detune[i] * spread));
        top = hz * (1.0f + ss_detune[SS_SIDES - 1] * spread);
    }
    uint32_t lv = 0;
    while (lv < WT_LEVELS - 1 && top * wt_level_harm[lv] > WT_MAX_HZ)
        lv++;
    o->len = wt_level_len[lv];
    if (o->supersaw) {
        o->base = wt_saw + wt_level_off[lv];
        o->pos = o->dpos = 0.0f;
        return;
    }
    o->base = wt_data + slot * (WT_FRAMES * WT_FRAME_STRIDE) + wt_level_off[lv];
    float target = shape * (float)(WT_FRAMES - 1);
    if (o->digital) {                       /* the nearest frame, no morph */
        o->pos = (float)(uint32_t)(target + 0.5f);
        o->dpos = 0.0f;
        return;
    }
    o->pos = e->fresh ? target : clampf(e->pos[k], 0.0f, (float)(WT_FRAMES - 1));
    o->dpos = (target - o->pos) * (1.0f / WT_BLOCK);
}

static inline float osc_sample(const struct wt_osc *o, uint32_t ph, float pos)
{
    int f0 = (int)pos;
    if (f0 > (int)WT_FRAMES - 2)
        f0 = WT_FRAMES - 2;
    float m = pos - (float)f0;
    const int16_t *a = o->base + f0 * WT_FRAME_STRIDE, *b = a + WT_FRAME_STRIDE;
    uint32_t u = (ph >> 9) * o->len;        /* the phase in samples, 9.23 fixed point */
    uint32_t i = u >> 23;
    float fr = (float)(u & 0x7FFFFFu) * (1.0f / 8388608.0f);
    float va = (float)a[i] + (float)(a[i + 1] - a[i]) * fr;
    float vb = (float)b[i] + (float)(b[i + 1] - b[i]) * fr;
    return va + (vb - va) * m;
}

/* One oscillator's block, stored into out (add 0) or added to it (add 1), times gain. While
 * the position stays between the same two frames for the whole block (the usual case:
 * Shape not moving, or moving slowly) the two frames are fixed; otherwise each sample
 * finds its frames. Returns the phase after the block. */
static inline __attribute__((always_inline)) uint32_t
osc_run(const struct wt_osc *o, uint32_t ph, float *out, float gain, const int add)
{
    float pos = o->pos, end = pos + o->dpos * (float)(WT_BLOCK - 1);
    int f0 = (int)pos;
    if (f0 > (int)WT_FRAMES - 2)
        f0 = WT_FRAMES - 2;
    int f1 = (int)end;
    if (f1 > (int)WT_FRAMES - 2)
        f1 = WT_FRAMES - 2;
    const uint32_t len = o->len, inc = o->inc;
    if (f0 == f1) {
        const int16_t *a = o->base + f0 * WT_FRAME_STRIDE, *b = a + WT_FRAME_STRIDE;
        float m = pos - (float)f0, dm = o->dpos;
        for (uint32_t n = 0; n < WT_BLOCK; n++) {
            uint32_t u = (ph >> 9) * len;   /* the phase in samples, 9.23 fixed point */
            uint32_t i = u >> 23;
            float fr = (float)(u & 0x7FFFFFu) * (1.0f / 8388608.0f);
            float a0 = (float)a[i], b0 = (float)b[i];
            float va = a0 + ((float)a[i + 1] - a0) * fr;
            float vb = b0 + ((float)b[i + 1] - b0) * fr;
            float v = (va + (vb - va) * m) * gain;
            out[n] = add ? out[n] + v : v;
            ph += inc;
            m += dm;
        }
        return ph;
    }
    for (uint32_t n = 0; n < WT_BLOCK; n++) {
        float v = osc_sample(o, ph, pos) * gain;
        out[n] = add ? out[n] + v : v;
        ph += inc;
        pos += o->dpos;
    }
    return ph;
}

/* Digital mode: one frame (the nearest), the nearest sample, 8-bit */
static inline __attribute__((always_inline)) uint32_t
osc_run_digital(const struct wt_osc *o, uint32_t ph, float *out, float gain, const int add)
{
    uint32_t f = (uint32_t)o->pos;
    const int16_t *a = o->base + (f > WT_FRAMES - 1 ? WT_FRAMES - 1 : f) * WT_FRAME_STRIDE;
    const uint32_t len = o->len, inc = o->inc;
    for (uint32_t n = 0; n < WT_BLOCK; n++) {
        uint32_t i = ((ph >> 9) * len) >> 23;
        float v = (float)(a[i] & ~0xFF) * gain;
        out[n] = add ? out[n] + v : v;
        ph += inc;
    }
    return ph;
}

/* The super saw: the centre saw and the side saws, linear interpolation in one level (the
 * Saw wave: the centre saw alone, at full level) */
static inline __attribute__((always_inline)) uint32_t
osc_run_supersaw(const struct wt_osc *o, uint32_t ph, uint32_t *side, float *out, float gain, const int add)
{
    const int16_t *a = o->base;
    const uint32_t len = o->len;
    const int saw = o->supersaw == OSC_SAW;
    float gc = saw ? gain : gain * SS_NORM, gs = gain * (SS_NORM * SS_SIDE_GAIN);
    for (uint32_t n = 0; n < WT_BLOCK; n++) {
        uint32_t u = (ph >> 9) * len;
        uint32_t i = u >> 23;
        float a0 = (float)a[i];
        float v = (a0 + ((float)a[i + 1] - a0) * ((float)(u & 0x7FFFFFu) * (1.0f / 8388608.0f))) * gc;
        ph += o->inc;
        out[n] = add ? out[n] + v : v;
    }
    if (saw)
        return ph;
    for (uint32_t k = 0; k < SS_SIDES; k++) {
        uint32_t q = side[k], qi = o->side_inc[k];
        for (uint32_t n = 0; n < WT_BLOCK; n++) {
            uint32_t u = (q >> 9) * len;
            uint32_t i = u >> 23;
            float a0 = (float)a[i];
            out[n] += (a0 + ((float)a[i + 1] - a0) * ((float)(u & 0x7FFFFFu) * (1.0f / 8388608.0f))) * gs;
            q += qi;
        }
        side[k] = q;
    }
    return ph;
}

/* An oscillator's block, whichever kind it is */
static inline __attribute__((always_inline)) uint32_t
osc_block(const struct wt_osc *o, uint32_t ph, uint32_t *side, float *out, float gain, const int add)
{
    if (o->supersaw)
        return osc_run_supersaw(o, ph, side, out, gain, add);
    if (o->digital)
        return osc_run_digital(o, ph, out, gain, add);
    return osc_run(o, ph, out, gain, add);
}

#define WT_LEVEL_GAIN       0.84f           /* the output level: a 4-note chord of WAVE's Init patch at
                                             * full velocity stays below the slot's clip (sy1 had 2.1,
                                             * VAP's Init level, which clipped on chords) */
#define WT_GAIN             (WT_LEVEL_GAIN / 32768.0f)
#define WT_NOISE_GAIN       0.45f           /* noise at Noise 1: about an oscillator's RMS */
#define WT_OUT_LIMIT        2.0f
#define F_FIXED_K           1.41421356f     /* the 24 dB types' first stage: Q 0.707 */
#define DRIVE_OCTAVES       4.0f            /* Drive 100 %: x16 (+24 dB) into the soft clip */
#define DRIVE_REF           0.35f           /* a signal at this peak keeps its peak at any Drive: about
                                             * a held note's at full velocity */

/* x limited to +-WT_OUT_LIMIT (vmaxnm / vminnm: a NaN becomes the limit) */
static inline float limit(float x)
{
    float lo = -WT_OUT_LIMIT, hi = WT_OUT_LIMIT;
    __asm("vmaxnm.f32 %0, %0, %1" : "+t"(x) : "t"(lo));
    __asm("vminnm.f32 %0, %0, %1" : "+t"(x) : "t"(hi));
    return x;
}
#define ENV_OCTAVES         8.0f            /* Env Amt +-1 (+-100 %): +-8 octaves */

/* The Mod Matrix: 6 slots of Src, Dest, Amt (-4..4, shown as +-400 %). Each slot adds
 * Amt x the source to the destination, per block, in the destination's units below. */
enum { SRC_AMP_ENV, SRC_FILTER_ENV, SRC_MOD_ENV, SRC_LFO1, SRC_LFO2, SRC_VELOCITY, SRC_KEY, MOD_SRCS };
enum { DST_POSITION, DST_POSITION1, DST_POSITION2, DST_PITCH, DST_PITCH1, DST_PITCH2, DST_MIX, DST_CUTOFF,
       DST_RESONANCE, DST_VOLUME, DST_NOISE, MOD_DESTS };
#define MOD_SLOTS           6u
#define MOD_SEMITONES       12.0f           /* Pitch: 100 % is an octave */
#define MOD_OCTAVES         4.0f            /* Cutoff: 100 % is 4 octaves */

static void mod_matrix(float *m, const float *src, const float *p)
{
    for (uint32_t d = 0; d < MOD_DESTS; d++)
        m[d] = 0.0f;
    for (uint32_t s = 0; s < MOD_SLOTS; s++) {
        const float *q = &p[WP_MTX + 3u * s];
        float amt = clampf(q[2], -4.0f, 4.0f);
        if (amt != 0.0f)
            m[list_pick(q[1], MOD_DESTS)] += amt * src[list_pick(q[0], MOD_SRCS)];
    }
}

/* `tempo`: the render context's BPM (for synced LFOs) */
static void wt_voice_render(struct wt_voice *e, const float *p, float *out, float tempo)
{
    float a0 = e->aenv.level;
    if (e->aenv.stage == ENV_IDLE) {        /* idle: silence, nearly free; Free Running LFOs run on */
        for (uint32_t k = 0; k < 2; k++)
            if (list_pick(p[WP_LFO1 + 4u * k + 2u], 3) == LFO_FREE)
                (void)lfo_step(e, k, p, tempo);
        for (uint32_t n = 0; n < WT_BLOCK; n += 4) {
            out[n] = 0.0f;
            out[n + 1] = 0.0f;
            out[n + 2] = 0.0f;
            out[n + 3] = 0.0f;
        }
        return;
    }
    float a1 = env_step(&e->aenv, &p[WP_AENV_ATT]);
    float fe = env_step(&e->fenv, &p[WP_FENV_ATT]);
    float src[MOD_SRCS], m[MOD_DESTS];
    src[SRC_AMP_ENV] = a1;
    src[SRC_FILTER_ENV] = fe;
    src[SRC_MOD_ENV] = env_step(&e->menv, &p[WP_MENV_ATT]);
    src[SRC_LFO1] = lfo_step(e, 0, p, tempo);
    src[SRC_LFO2] = lfo_step(e, 1, p, tempo);
    src[SRC_VELOCITY] = clampf(e->volume, 0.0f, 1.0f);
    src[SRC_KEY] = clampf((e->pitch - 60.0f) * (1.0f / 60.0f), -2.0f, 2.0f);
    mod_matrix(m, src, p);
    /* the glide, then each oscillator's pitch */
    if (e->glide_step > 0.0f) {
        float d = e->note - e->pitch;
        if (d > e->glide_step)
            e->pitch += e->glide_step;
        else if (d < -e->glide_step)
            e->pitch -= e->glide_step;
        else
            e->pitch = e->note;
    } else {
        e->pitch = e->note;
    }
    float fine = clampf(p[WP_FINE], -100.0f, 100.0f) * 0.01f;
    float base = e->pitch + fine + clampf(e->bend, -48.0f, 48.0f);
    float pitch1 = clampf((m[DST_PITCH] + m[DST_PITCH1]) * MOD_SEMITONES, -96.0f, 96.0f);
    float pitch2 = clampf((m[DST_PITCH] + m[DST_PITCH2]) * MOD_SEMITONES, -96.0f, 96.0f);
    struct wt_osc o[2];
    osc_setup(&o[0], e, p, 0, base + clampf(p[WP_TUNE1], -36.0f, 36.0f) + pitch1,
              m[DST_POSITION] + m[DST_POSITION1]);
    osc_setup(&o[1], e, p, 1, base + clampf(p[WP_TUNE2], -36.0f, 36.0f)
                                 + clampf(p[WP_DETUNE], 0.0f, 100.0f) * 0.01f + pitch2,
              m[DST_POSITION] + m[DST_POSITION2]);
    /* the filter: Cutoff x 2^(Env Amt x 8 x envelope + Note Track x (note - 60) / 12 + the
     * Mod Matrix's octaves) */
    float oct = clampf(p[WP_ENVAMT], -1.0f, 1.0f) * ENV_OCTAVES * fe
                + clampf(p[WP_TRACK], -2.0f, 2.0f) * (e->pitch - 60.0f) * (1.0f / 12.0f)
                + clampf(m[DST_CUTOFF] * MOD_OCTAVES, -16.0f, 16.0f);
    float fc = clampf(clampf(p[WP_CUTOFF], 20.0f, 20000.0f) * exp2f_fast(oct), 20.0f, 18000.0f);
    float g = tan_pade(3.14159265f * fc / WT_RATE);
    float res = clampf(clampf(p[WP_RES], 0.0f, 1.5f) + m[DST_RESONANCE], 0.0f, 1.5f);
    float k = 2.0f - res * (1.98f / 1.5f);
    uint32_t type = wt_filter_type[(uint32_t)clampf(p[WP_TYPE] + 0.5f, 0.0f, 14.0f)];
    struct wt_svf f1, f2;
    struct wt_ladder lad;
    svf_setup(&f2, g, k, type);
    svf_setup(&f1, g, F_FIXED_K, type);
    ladder_setup(&lad, g, res);
    int two = (type & F_24DB) != 0;
    float mix = (clampf(clampf(p[WP_MIX], -1.0f, 1.0f) + m[DST_MIX], -1.0f, 1.0f) + 1.0f) * 0.5f;
    float vol = clampf(e->volume, 0.0f, 2.0f) * WT_GAIN * clampf(1.0f + m[DST_VOLUME], 0.0f, 4.0f);
    float g1 = (1.0f - mix) * vol, g2 = mix * vol;
    float gn = clampf(clampf(p[WP_NOISE], 0.0f, 1.0f) + m[DST_NOISE], 0.0f, 1.0f)
               * (WT_NOISE_GAIN * 32768.0f / 2147483648.0f) * vol;
    float amp = a0, damp = (a1 - a0) * (1.0f / WT_BLOCK);
    /* the oscillators (and the noise) into out, then the filter and the amp in place */
    e->phase[0] = osc_block(&o[0], e->phase[0], e->side[0], out, g1, 0);
    e->phase[1] = osc_block(&o[1], e->phase[1], e->side[1], out, g2, 1);
    if (gn > 0.0f) {
        uint32_t nz = e->noise;
        for (uint32_t n = 0; n < WT_BLOCK; n++) {
            nz = nz * 1664525u + 1013904223u;
            out[n] += (float)(int32_t)nz * gn;
        }
        e->noise = nz;
    }
    float drive = clampf(p[WP_DRIVE], 0.0f, 1.0f);
    if (drive > 0.0f) {                     /* Drive: the filter's input through the soft clip */
        float dg = exp2f_fast(drive * DRIVE_OCTAVES);
        float mk = DRIVE_REF / sat(DRIVE_REF * dg);
        for (uint32_t n = 0; n < WT_BLOCK; n++)
            out[n] = sat(out[n] * dg) * mk;
    }
    float ic[4] = {e->ic[0], e->ic[1], e->ic[2], e->ic[3]};
    if (type & F_LADDER) {
        for (uint32_t n = 0; n < WT_BLOCK; n++) {
            out[n] = limit(ladder_run(&lad, ic, out[n]) * amp);
            amp += damp;
        }
    } else if (type & F_OB) {
        for (uint32_t n = 0; n < WT_BLOCK; n++) {
            float x = two ? ob_run(&f1, &ic[2], out[n]) : out[n];
            out[n] = limit(ob_run(&f2, &ic[0], x) * amp);
            amp += damp;
        }
    } else if (two) {
        for (uint32_t n = 0; n < WT_BLOCK; n++) {
            out[n] = limit(svf_run(&f2, &ic[0], svf_run(&f1, &ic[2], out[n])) * amp);
            amp += damp;
        }
    } else {
        for (uint32_t n = 0; n < WT_BLOCK; n++) {
            out[n] = limit(svf_run(&f2, &ic[0], out[n]) * amp);
            amp += damp;
        }
    }
    e->pos[0] = clampf(o[0].pos + o[0].dpos * (float)WT_BLOCK, 0.0f, (float)(WT_FRAMES - 1));
    e->pos[1] = clampf(o[1].pos + o[1].dpos * (float)WT_BLOCK, 0.0f, (float)(WT_FRAMES - 1));
    for (uint32_t i = 0; i < 4; i++)        /* flushed when the voice goes idle */
        e->ic[i] = e->aenv.stage == ENV_IDLE ? 0.0f : ic[i];
    e->fresh = 0;
}

#endif
